begin;

-- CLASS_WORK_STATUS: druid:text=READY;mechanics=NOT_AUDITED
-- CLASS_STATUS_LEDGER: src/rule-templates/CLASS_WORK_STATUS.md
-- PRESENTATION ONLY. Changes template copy and feature label/description/authorComment only.

create or replace function private.druid_patch_feature_text(
  p_catalog_key text,
  p_level integer,
  p_feature_id text,
  p_label text,
  p_description text,
  p_author_comment text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.rule_template_levels rtl
  set mechanics = (
    select coalesce(
      jsonb_agg(
        case
          when mechanic->>'type' = 'grant'
            and mechanic->>'target' = 'feature'
            and mechanic->>'id' = p_feature_id
          then jsonb_set(
            jsonb_set(
              jsonb_set(mechanic, '{payload,label}', to_jsonb(p_label), true),
              '{payload,description}', to_jsonb(p_description), true
            ),
            '{payload,authorComment}', to_jsonb(p_author_comment), true
          )
          else mechanic
        end
        order by ord
      ),
      '[]'::jsonb
    )
    from jsonb_array_elements(coalesce(rtl.mechanics, '[]'::jsonb)) with ordinality as items(mechanic, ord)
  )
  where rtl.level = p_level
    and rtl.template_id in (
      select rt.id
      from public.rule_templates rt
      where rt.is_active and rt.catalog_key = p_catalog_key
    );
end;
$$;

create or replace function private.druid_patch_template_copy(
  p_catalog_key text,
  p_summary text,
  p_author_description text,
  p_author_comment text
)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.rule_templates
  set mechanical_summary = p_summary,
      author_description = p_author_description,
      author_comment = p_author_comment,
      rules_meta = coalesce(rules_meta, '{}'::jsonb)
        || jsonb_build_object(
          'class_work_status', jsonb_build_object('text','READY','mechanics','NOT_AUDITED'),
          'reference_delivery', 'SYNCED_2026_08_29',
          'text_contract', 'gm_resolvable_rule_text'
        ),
      updated_at = now()
  where is_active and catalog_key = p_catalog_key;
$$;

select private.druid_patch_template_copy('class:druid','Полный подготовленный заклинатель природы с проектной Дикой формой по модели 2014 года: 2 использования, HP и физические параметры зверя, полное восстановление после короткого или долгого отдыха.','Друид сочетает полный прогресс подготовленной природной магии с Дикой формой, Диким спутником, обменом ячеек и формы и одним из восьми поддерживаемых Кругов. В MEGANOT базовая Дикая форма намеренно использует HP зверя и два использования с восстановлением после короткого или долгого отдыха.','Природа редко пишет документацию. Поэтому пришлось сделать это за неё — до того, как ещё один медведь заявит, что «так было задумано».');
select private.druid_patch_feature_text('class:druid',2,'druid-wild-shape-rules','Дикая форма','Действием потратьте 1 из 2 использований Дикой формы и превратитесь в зверя, которого уже видели и который удовлетворяет пределу CR и ограничениям перемещения. Форма длится число часов, равное половине уровня друида с округлением вниз; выйти раньше можно бонусным действием. Эта кампания использует модель 2014 года: Сила, Ловкость, Телосложение, HP и физические возможности берутся у зверя, а Интеллект, Мудрость, Харизма, личность и мировоззрение остаются вашими. Сохраняются ваши владения навыками и спасбросками и добавляются владения зверя; при совпадении используйте больший итоговый бонус. При 0 HP формы вы возвращаетесь в обычный облик, а избыточный урон переносится на обычные HP; форма также заканчивается при потере сознания или смерти. До «Заклинаний зверя» в форме нельзя накладывать заклинания, но уже действующая концентрация не прерывается. Классовые, видовые и иные способности сохраняются, если новый облик физически способен ими пользоваться; особые чувства работают только если они есть у зверя. Для каждого предмета снаряжения при превращении выберите: он падает, остаётся надетым/переносимым либо сливается с формой; слитый предмет не действует. Запас всегда 2 использования, и оба полностью восстанавливаются после короткого или долгого отдыха.','Волк не обязан знать бухгалтерию. Игрок — обязан. Два использования, оба возвращаются после отдыха; всё остальное уже вопрос того, насколько убедительно вы изображаете волка.');
select private.druid_patch_feature_text('class:druid',2,'druid-wild-companion-rules','Дикий спутник','Магическим действием сотворите «Поиск фамильяра» без материальных компонентов. Для одного применения выберите ровно один способ оплаты: потратить 1 использование Дикой формы либо подходящую ячейку заклинаний; платить оба ресурса не нужно. Фамильяр, призванный этим способом, имеет тип Фея и исчезает, когда вы заканчиваете следующий долгий отдых.','Если самому превращаться неудобно, можно временно нанять зверя. Удивительно, но кадровая политика природы иногда понятнее человеческой.');
select private.druid_patch_feature_text('class:druid',3,'druid-subclass-unlock','Круг друида','На 3 уровне выберите один Круг друида. Выбор постоянный; способности выбранного Круга становятся доступны на указанных для него уровнях именно класса Друид, а не общего уровня персонажа.','На третьем уровне друид наконец уточняет, какой именно разновидностью проблемы он намерен стать.');
select private.druid_patch_feature_text('class:druid',4,'druid-asi-4','Улучшение характеристик','Получите талант «Улучшение характеристик» либо другой общий талант, требованиям которого персонаж соответствует. Эффекты выбранного таланта определяются его собственной карточкой.','Редкий случай: никакой мистики, просто повышение квалификации.');
select private.druid_patch_feature_text('class:druid',8,'druid-asi-8','Улучшение характеристик','Получите талант «Улучшение характеристик» либо другой общий талант, требованиям которого персонаж соответствует. Эффекты выбранного таланта определяются его собственной карточкой.','Второе повышение. Деревья всё ещё не выдали диплом, но прогресс есть.');
select private.druid_patch_feature_text('class:druid',12,'druid-asi-12','Улучшение характеристик','Получите талант «Улучшение характеристик» либо другой общий талант, требованиям которого персонаж соответствует. Эффекты выбранного таланта определяются его собственной карточкой.','К двенадцатому уровню обычно уже понятно, что именно нужно улучшать. Иногда это Мудрость. Иногда планирование.');
select private.druid_patch_feature_text('class:druid',16,'druid-asi-16','Улучшение характеристик','Получите талант «Улучшение характеристик» либо другой общий талант, требованиям которого персонаж соответствует. Эффекты выбранного таланта определяются его собственной карточкой.','Последнее обычное повышение перед тем, как правила начнут употреблять слово «эпический».');
select private.druid_patch_feature_text('class:druid',5,'druid-wild-resurgence','Дикое возрождение','Есть два разных обмена. Первый: если у вас 0 использований Дикой формы, один раз на каждом своём ходу без действия можно потратить 1 ячейку заклинаний любого уровня и восстановить ровно 1 использование Дикой формы; уровень ячейки ничего не меняет. Второй: без действия потратьте 1 использование Дикой формы и восстановите одну потраченную ячейку именно 1 уровня; этот обратный обмен можно выполнить только 1 раз до следующего долгого отдыха.','Курс обмена намеренно грабительский. Ячейка девятого уровня всё равно покупает одного медведя, а не медведя с недвижимостью.');
select private.druid_patch_feature_text('class:druid',7,'druid-elemental-fury','Стихийная ярость','Один раз выберите одну ветку. «Могущественные заклинания»: когда заговор друида наносит урон, добавьте к его урону модификатор Мудрости. «Первобытный удар»: один раз на каждом своём ходу после попадания оружием или атакой зверя в Дикой форме добавьте 1к8 урона и выберите его тип при попадании — холод, огонь, электричество или звук. На 15 уровне автоматически усиливается эта же выбранная ветка; повторного выбора нет.','Когда магии и превращений мало, остаётся добавить стихию непосредственно в удар. Природа ценит запасные планы.');
select private.druid_patch_feature_text('class:druid',15,'druid-improved-elemental-fury','Улучшенная стихийная ярость','Усильте ветку Стихийной ярости, выбранную на 7 уровне. Если выбраны «Могущественные заклинания», сохраняется добавление Мудрости к урону заговора и дальность заговора друида с исходной дальностью не меньше 10 футов увеличивается на 300 футов. Если выбран «Первобытный удар», его дополнительный стихийный урон увеличивается с 1к8 до 2к8; частота остаётся один раз на каждом своём ходу, а тип урона по-прежнему выбирается при попадании.','То же решение, просто теперь последствия можно наблюдать с другого конца поля.');
select private.druid_patch_feature_text('class:druid',18,'druid-beast-spells','Заклинания зверя','Пока действует Дикая форма, вы можете накладывать заклинания, не возвращаясь в обычный облик. Исключение: так нельзя сотворить заклинание, если у его материального компонента указана денежная стоимость или компонент расходуется заклинанием. Остальные требования конкретного заклинания продолжают действовать, если эта способность прямо их не отменяет.','Медведь, который рычит, — проблема. Медведь, который завершает рычание заклинанием, — причина сменить профессию.');
select private.druid_patch_feature_text('class:druid',19,'druid-epic-boon','Эпический дар','Получите один эпический талант либо другой талант, требованиям которого персонаж соответствует. Все эффекты, выборы и ограничения определяются полной карточкой выбранного таланта.','На девятнадцатом уровне слово «дар» означает, что правила перестали притворяться, будто вы обычный сотрудник экспедиции.');
select private.druid_patch_feature_text('class:druid',20,'druid-archdruid','Архидруид','Когда бросается инициатива и у вас 0 использований Дикой формы, восстановите 1 использование. Один раз между долгими отдыхами без действия можно потратить 1 или 2 оставшихся использования Дикой формы и восстановить одну потраченную ячейку: её уровень равен удвоенному числу потраченных использований, то есть 1 форма создаёт одну ячейку 2 уровня, а 2 формы — одну ячейку 4 уровня. Этот обмен создаёт одну ячейку, а не несколько меньших. Кроме того, тело стареет в десять раз медленнее: за каждые 10 прошедших лет биологически проходит 1 год.','Если природа держала вас до двадцатого уровня, похоже, увольнение уже не предусмотрено.');

select private.druid_patch_template_copy('subclass:druid:circle-of-dreams','Фейское лечение из отдельного запаса кубов, защищённый отдых, телепортация через скрытые пути и разовые магические путешествия после отдыха.','Круг Снов связывает друида с благожелательными силами Страны Фей: сначала он лечит союзников фейской энергией, затем скрывает лагерь, перемещается по невидимым тропам и использует сон как путь для магии и путешествия.','Сны удобны как дорога ровно до момента, когда кто-то припарковал на ней кошмар. Этот Круг хотя бы носит аптечку.');
select private.druid_patch_feature_text('subclass:druid:circle-of-dreams',2,'druid-circle-of-dreams-circle-of-dreams-l2-1-feature','Бальзам Летнего Двора','У вас есть запас к6 фейской энергии, число кубов в котором равно уровню друида. Бонусным действием выберите видимого союзника в пределах 120 футов и потратьте от 1 куба до половины уровня друида с округлением вниз. Бросьте потраченные кубы: союзник восстанавливает HP, равные сумме бросков, и дополнительно получает 1 временный HP за каждый потраченный куб. Все потраченные кубы возвращаются после долгого отдыха.','Фейская медицина: лечит быстро, светится подозрительно и бухгалтерию ведёт кубами.');
select private.druid_patch_feature_text('subclass:druid:circle-of-dreams',6,'druid-circle-of-dreams-hearth-of-moonlight-and-shadow-l6-1-feature','Очаг лунного света и тени','В начале короткого или долгого отдыха коснитесь точки в пространстве. Вокруг неё появляется невидимая сфера радиусом 30 футов; полное укрытие блокирует её распространение. Пока вы и ваши союзники находитесь внутри сферы, они получают +5 к проверкам Ловкости (Скрытность) и Мудрости (Восприятие), а свет открытого огня внутри сферы не виден снаружи. Сфера исчезает в конце отдыха или раньше, если вы покидаете её.','Наконец-то палатка, которую не видно по костру за три холма. Жаль, что храп правило не глушит.');
select private.druid_patch_feature_text('subclass:druid:circle-of-dreams',10,'druid-circle-of-dreams-hidden-paths-l10-1-feature','Скрытые пути','Бонусным действием в свой ход телепортируйтесь на расстояние до 60 футов в свободное видимое место. Вместо этого действием можно коснуться согласного существа и телепортировать его на расстояние до 30 футов в свободное место, которое вы видите. Число применений равно модификатору Мудрости, минимум 1; все применения возвращаются после долгого отдыха.','Если фея говорит, что знает короткую дорогу, обычно это угроза. Здесь хотя бы дальность указана.');
select private.druid_patch_feature_text('subclass:druid:circle-of-dreams',14,'druid-circle-of-dreams-walker-in-dreams-l14-1-feature','Странник во снах','Когда заканчиваете короткий отдых, выберите и сотворите без ячейки и материальных компонентов одно заклинание: «Сон» — при этом вы являетесь посланником, «Наблюдение» или «Круг телепортации». Особая версия «Круга телепортации» ведёт не к постоянному кругу, а в последнее место на текущем плане, где вы завершили долгий отдых. Если на текущем плане вы ещё не завершали долгий отдых, это заклинание не срабатывает и использование способности не расходуется. После успешного применения способность недоступна до окончания долгого отдыха.','Сон как транспортная инфраструктура звучит нелепо ровно до первого раза, когда вам не пришлось идти обратно пешком.');

select private.druid_patch_template_copy('subclass:druid:circle-of-spores','Ореол спор наносит некротический урон реакцией, Симбиотическая сущность тратит Дикую форму на временные HP и усиление ближнего боя, а поздние способности поднимают трупы и создают область спор.','Круг Спор рассматривает разложение как часть природного цикла. Его правила строятся вокруг Ореола спор, Симбиотической сущности и эффектов, которые используют трупы и области спор, а не обычное превращение в зверя.','Грибы умеют перерабатывать почти всё. Не спрашивайте, входите ли вы в список сырья.');
select private.druid_patch_feature_text('subclass:druid:circle-of-spores',2,'druid-circle-of-spores-circle-of-spores-l2-1-feature','Ореол спор и Симбиотическая сущность','Заклинания Круга: «Леденящее прикосновение» доступно с 2 уровня; с 3 — «Слепота/Глухота» и «Нетленность»; с 5 — «Оживление мертвецов» и «Газообразная форма»; с 7 — «Увядание» и «Замешательство»; с 9 — «Смертоносное облако» и «Заражение». Эти заклинания всегда подготовлены, не занимают обычный лимит, а заклинание не из списка друида считается для вас заклинанием друида. Ореол спор: когда видимое существо входит в пространство в пределах 10 футов от вас или начинает там ход, реакцией заставьте его совершить спасбросок Телосложения против Сл ваших заклинаний. При провале оно получает 1к4 некротического урона, при успехе — 0; куб становится 1к6 на 6 уровне, 1к8 на 10 и 1к10 на 14. Симбиотическая сущность: действием потратьте 1 Дикую форму, не превращаясь в зверя, и получите временные HP = 4 × уровень друида. На 10 минут, пока эти временные HP не закончились и пока вы снова не используете Дикую форму, при нанесении урона Ореолом спор бросайте его куб дважды и складывайте результаты, а каждое попадание вашей ближней атакой оружием наносит дополнительно 1к6 некротического урона.','Споры дают два режима работы: тихо портят день реакцией или официально становятся вашим боевым партнёром. Во втором случае лучше не нюхать.');
select private.druid_patch_feature_text('subclass:druid:circle-of-spores',6,'druid-circle-of-spores-fungal-infestation-l6-1-feature','Грибковое заражение','Когда Зверь или Гуманоид Маленького или Среднего размера умирает в пределах 10 футов от вас, реакцией оживите его с 1 HP. Он использует статблок Зомби и остаётся оживлённым 1 час, после чего падает и умирает. В бою его ход идёт сразу после вашего; он выполняет мысленные команды и из действий может использовать только Атаку, совершая одну ближнюю атаку. Число применений равно модификатору Мудрости, минимум 1; все применения возвращаются после долгого отдыха.','Это не воскрешение. Это очень временное продление трудового договора с крайне спорным отделом кадров.');
select private.druid_patch_feature_text('subclass:druid:circle-of-spores',10,'druid-circle-of-spores-spreading-spores-l10-1-feature','Распространение спор','Пока активна Симбиотическая сущность, бонусным действием выберите точку в пределах 30 футов: там появляется куб спор размером 10 футов на 1 минуту. Он исчезает раньше, если вы создаёте новый такой куб, бонусным действием прекращаете эффект или заканчивается Симбиотическая сущность. Когда существо входит в куб или начинает там ход, оно совершает спасбросок Телосложения против Сл ваших заклинаний; при провале получает текущий урон Ореола спор, при успехе — 0. Одно существо может получить этот урон от куба не чаще одного раза за ход. Пока куб существует, вы не можете использовать реакцию Ореола спор.','Теперь грибок занимает площадь. Именно так обычно начинается фраза, после которой хозяин таверны просит вас уйти.');
select private.druid_patch_feature_text('subclass:druid:circle-of-spores',14,'druid-circle-of-spores-fungal-body-l14-1-feature','Грибковое тело','Вы получаете иммунитет к состояниям Ослеплён, Оглушён слухом, Испуган и Отравлен. Кроме того, критическое попадание по вам считается обычным попаданием, если только в момент попадания вы не Недееспособны.','Организм окончательно договорился с грибами. Хорошая новость — устойчивость. Плохая — формулировка «договорился с грибами».');

select private.druid_patch_template_copy('subclass:druid:circle-of-the-shepherd','Разговаривает со зверями, призывает Духовный тотем Медведя, Ястреба или Единорога и усиливает Зверей и Фей, созданных своими заклинаниями.','Круг Пастыря специализируется на зверях, феях и призыве. Духовный тотем создаёт одну из трёх аур, а последующие способности усиливают существ, которых друид призывает или создаёт заклинаниями.','Пастырь отвечает за стадо. Даже когда стадо вооружено, спорит и требует отдельную инициативу.');
select private.druid_patch_feature_text('subclass:druid:circle-of-the-shepherd',2,'druid-circle-of-the-shepherd-circle-of-the-shepherd-l2-1-feature','Речь леса и Духовный тотем','Речь леса: вы умеете говорить, читать и писать на Сильване; Звери понимают вашу речь, а вы понимаете смысл их звуков и движений. Это не делает зверя дружелюбным автоматически. Духовный тотем: бонусным действием призовите нематериального духа в видимой точке в пределах 60 футов. Он не является существом или объектом, создаёт ауру радиусом 30 футов, существует 1 минуту и бонусным действием может быть перемещён до 60 футов в видимую точку. После призыва новый тотем недоступен до короткого или долгого отдыха. Выберите дух. Медведь: выбранные вами существа в ауре в момент появления получают временные HP = 5 + уровень друида; вы и союзники в ауре имеете преимущество на проверки и спасброски Силы. Ястреб: когда существо совершает бросок атаки по цели внутри ауры, реакцией дайте этой атаке преимущество; вы и союзники в ауре имеют преимущество на проверки Мудрости (Восприятие). Единорог: вы и союзники имеете преимущество на проверки характеристик для обнаружения существ в ауре; когда вы накладываете заклинание с ячейкой, восстанавливающее HP любому существу, каждое выбранное вами существо внутри ауры дополнительно восстанавливает HP, равные вашему уровню друида.','Медведь укрепляет, Ястреб помогает попасть, Единорог лечит. Если забыли, какой вызвали, посмотрите на огромный призрачный силуэт над лагерем.');
select private.druid_patch_feature_text('subclass:druid:circle-of-the-shepherd',6,'druid-circle-of-the-shepherd-mighty-summoner-l6-1-feature','Могучий призыватель','Каждый Зверь или Фея, которого вы призвали или создали своим заклинанием, появляется с дополнительными HP: +2 HP за каждую его Кость Хитов. Кроме того, урон его естественного оружия считается магическим при определении сопротивления и иммунитета к немагическим атакам и урону.','Если вы привели на бой волка из магии, Круг хотя бы выдаёт ему медицинскую страховку и магические зубы.');
select private.druid_patch_feature_text('subclass:druid:circle-of-the-shepherd',10,'druid-circle-of-the-shepherd-guardian-spirit-l10-1-feature','Дух-хранитель','Когда Зверь или Фея, которого вы призвали или создали своим заклинанием, заканчивает свой ход внутри ауры вашего Духовного тотема, это существо восстанавливает HP, равные половине вашего уровня друида. Эффект проверяется в конце каждого его хода и работает только пока существо находится в ауре.','Тотем теперь не только морально поддерживает вызванных существ, но и буквально чинит их по окончании смены.');
select private.druid_patch_feature_text('subclass:druid:circle-of-the-shepherd',14,'druid-circle-of-the-shepherd-faithful-summons-l14-1-feature','Верный призыв','Если ваши HP падают до 0 или вы против своей воли получаете состояние Недееспособен, способность срабатывает немедленно и даёт эффект «Призыва животных», как если бы заклинание было сотворено ячейкой 9 уровня: появляются четыре выбранных вами Зверя CR 2 или ниже в пределах 20 футов от вас. Если вы не отдаёте им команд, они защищают вас и атакуют угрозы. Эффект длится 1 час, не требует концентрации и может быть прекращён вами без действия. После срабатывания способность недоступна до долгого отдыха.','План аварийного реагирования: если пастух падает, стадо приходит само. Наконец-то нормальная организация труда.');

select private.druid_patch_template_copy('subclass:druid:circle-of-wildfire','Тратит Дикую форму на Огненного духа с собственным статблоком, атакой и телепортацией; дух усиливает огненную и лечебную магию и позднее может сгореть вместо друида.','Круг Лесного Пожара связывает друида с Огненным духом. Дух действует сразу после друида, атакует, телепортирует союзников и становится точкой происхождения части заклинаний; поздние способности превращают смерть существ в лечебное или разрушительное пламя.','Пожар уничтожает старое и освобождает место новому. Особенно убедительно эта философия звучит, когда горит не ваша сумка.');
select private.druid_patch_feature_text('subclass:druid:circle-of-wildfire',2,'druid-circle-of-wildfire-circle-of-wildfire-l2-1-feature','Заклинания Круга и Огненный дух','Заклинания Круга всегда подготовлены и не занимают обычный лимит: с 2 уровня «Пылающие ладони» и «Лечение ран»; с 3 — «Пылающая сфера» и «Палящий луч»; с 5 — «Рост растений» и «Возвращение к жизни»; с 7 — «Аура жизни» и «Огненный щит»; с 9 — «Небесное пламя» и «Массовое лечение ран». Заклинание из этого списка, которого обычно нет у друида, всё равно считается для вас заклинанием друида. Призыв духа: действием потратьте 1 Дикую форму и выберите свободное видимое место в пределах 30 футов. При появлении каждое существо, кроме вас, в пределах 10 футов от духа совершает спасбросок Ловкости против Сл ваших заклинаний; при провале получает 2к6 огненного урона, при успехе — 0. Дух — Маленький Элементаль: КД 13; HP = 5 + 5 × уровень друида; скорость 30 футов, полёт 30 футов с зависанием; иммунитет к огню и состояниям Очарован, Испуган, Схвачен, Сбит с ног и Опутан; тёмное зрение 60 футов; понимает ваши языки; использует ваш бонус мастерства. Он дружелюбен, делит вашу инициативу и ходит сразу после вас. Без команды он Уклоняется; бонусным действием в свой ход вы можете приказать ему выполнить другое действие, а если вы Недееспособны, он выбирает действие сам. «Семя пламени»: дальняя атака оружием с вашим модификатором атаки заклинанием по видимой цели в 60 футах; попадание наносит 1к6 + бонус мастерства огненного урона. «Огненная телепортация»: дух и выбранные согласные существа в 5 футах телепортируются до 15 футов в видимые свободные места; затем каждое существо в 5 футах от оставленной духом точки совершает спасбросок Ловкости против Сл ваших заклинаний и при провале получает 1к6 + бонус мастерства огненного урона, при успехе — 0. Дух существует 1 час, до 0 HP, до нового призыва духа или до вашей смерти.','Это фамильяр, если фамильяр способен эвакуировать группу взрывом. Формально — дух. Практически — пожарная служба с противоположной специализацией.');
select private.druid_patch_feature_text('subclass:druid:circle-of-wildfire',6,'druid-circle-of-wildfire-enhanced-bond-l6-1-feature','Усиленная связь','Пока ваш Огненный дух призван, каждый раз когда вы накладываете заклинание, которое наносит огненный урон или восстанавливает HP, бросьте 1к8 и добавьте результат к одному броску урона или лечения этого заклинания. Кроме того, если дальность заклинания не «На себя», точкой происхождения заклинания по вашему выбору можете быть вы или Огненный дух.','Теперь дух не просто стоит рядом с магией, а официально участвует в её производстве. Профсоюз пока не создан.');
select private.druid_patch_feature_text('subclass:druid:circle-of-wildfire',10,'druid-circle-of-wildfire-cauterizing-flames-l10-1-feature','Прижигающее пламя','Когда существо Маленького размера или больше умирает в пределах 30 футов от вас или вашего Огненного духа, в пространстве трупа на 1 минуту появляется безвредное спектральное пламя. Когда видимое вами существо входит в это пространство, реакцией погасите пламя и выберите результат: вошедшее существо либо восстанавливает 2к10 + модификатор Мудрости HP, либо получает столько же огненного урона. Реакцию можно использовать число раз, равное бонусу мастерства; все применения возвращаются после долгого отдыха.','Одно и то же пламя умеет лечить и жечь. Не перепутайте пункт меню — медицина и кремация слишком близко расположены.');
select private.druid_patch_feature_text('subclass:druid:circle-of-wildfire',14,'druid-circle-of-wildfire-blazing-revival-l14-1-feature','Пылающее возрождение','Если ваш Огненный дух находится в пределах 120 футов, когда урон опускает ваши HP до 0 и вы из-за этого теряете сознание, можно немедленно опустить HP духа до 0. После этого вы восстанавливаете HP в количестве половины своего максимума и сразу встаёте. После такого спасения способность недоступна до долгого отдыха.','Дух буквально сгорает вместо вас. На фоне обычных условий страхования это почти трогательно.');

select private.druid_patch_template_copy('subclass:druid:land','После каждого долгого отдыха выбирает тип земли, который задаёт постоянно подготовленные заклинания и сопротивление; также лечит и ранит одной областью, восстанавливает магию и создаёт переносимое святилище.','Круг Земли каждый день настраивается на один из четырёх типов местности. Выбранная земля определяет набор всегда подготовленных заклинаний и позднее тип сопротивления, а остальные способности работают независимо от конкретной местности.','Земля не обязана быть родиной. Достаточно утром решить, какая именно сегодня вас терпит.');
select private.druid_patch_feature_text('subclass:druid:land',3,'land-spells-feature','Заклинания Круга Земли','После каждого долгого отдыха выберите одну землю; до следующего выбора у вас всегда подготовлены перечисленные заклинания для вашего текущего уровня друида и ниже. Засушливая: 3 уровень — «Размытие», «Пылающие ладони», «Огненный снаряд»; 5 — «Огненный шар»; 7 — «Увядание»; 9 — «Каменная стена». Полярная: 3 — «Облако тумана», «Удержание личности», «Луч холода»; 5 — «Ледяная буря»; 7 — «Ледяной шторм»; 9 — «Конус холода». Умеренная: 3 — «Туманный шаг», «Электрошок», «Сон»; 5 — «Молния»; 7 — «Свобода передвижения»; 9 — «Шаг через деревья». Тропическая: 3 — «Кислотные брызги», «Луч болезни», «Паутина»; 5 — «Зловонное облако»; 7 — «Превращение»; 9 — «Нашествие насекомых». Эти заклинания не занимают обычный лимит подготовки.','Четыре климата, четыре набора инструментов. Погода впервые стала чем-то вроде меню настроек.');
select private.druid_patch_feature_text('subclass:druid:land',3,'lands-aid-rules','Помощь земли','Магическим действием потратьте 1 использование Дикой формы и выберите точку в пределах 60 футов. На миг появляется сфера радиусом 10 футов. Каждое выбранное вами существо в сфере совершает спасбросок Телосложения против Сл ваших заклинаний: при провале получает 2к6 некротического урона, при успехе — половину. Одно выбранное вами существо в этой же области восстанавливает 2к6 HP. На 10 уровне и урон, и лечение становятся 3к6; на 14 уровне — 4к6.','Одна и та же клумба лечит союзника и высасывает жизнь из врага. Очень эффективное землепользование.');
select private.druid_patch_feature_text('subclass:druid:land',6,'land-natural-recovery-rules','Природное восстановление','Первый эффект: один раз до следующего долгого отдыха можно сотворить без расхода ячейки одно подготовленное заклинание 1 уровня или выше, полученное от «Заклинаний Круга Земли». Второй эффект: когда заканчиваете короткий отдых, выберите потраченные ячейки для восстановления; сумма их уровней не может превышать половину уровня друида с округлением вверх, и нельзя восстановить ячейку 6 уровня или выше. После такого восстановления ячеек этот второй эффект снова доступен только после долгого отдыха.','Земля возвращает магию после обеда. Удивительно разумная система по сравнению с большинством работодателей.');
select private.druid_patch_feature_text('subclass:druid:land',10,'land-natures-ward-rules','Защита природы','Вы получаете иммунитет к состоянию Отравлен. Кроме того, текущая земля из «Заклинаний Круга Земли» даёт сопротивление урону: Засушливая — огню; Полярная — холоду; Умеренная — электричеству; Тропическая — яду. Если после долгого отдыха меняется земля, одновременно меняется и это сопротивление.','Погода теперь влияет не только на гардероб, но и на то, чем вас сложнее убить.');
select private.druid_patch_feature_text('subclass:druid:land',14,'land-sanctuary-rules','Святилище природы','Магическим действием потратьте 1 использование Дикой формы и создайте на земле в пределах 120 футов куб спектральных деревьев и лоз размером 15 футов. Он существует 1 минуту и исчезает раньше, если вы Недееспособны или умираете. Вы и ваши союзники внутри куба имеете укрытие наполовину; союзники внутри также получают текущее сопротивление вашей «Защиты природы». Бонусным действием можно переместить весь куб на расстояние до 60 футов, но его новое положение также должно быть на земле в пределах 120 футов от вас.','Передвижной лес — решение проблемы «мы пришли без укрытия». Остаётся объяснить деревьям логистику.');

select private.druid_patch_template_copy('subclass:druid:moon','Боевая специализация проектной Дикой формы: повышает предел CR и КД зверя, разрешает круговые заклинания в форме, добавляет излучающий урон и открывает Лунный шаг.','Круг Луны использует правила подкласса 2024 поверх проектной базовой Дикой формы 2014. Максимальный CR и защита формы улучшаются, но временные HP 3 × уровень друида из версии 2024 намеренно не добавляются: MEGANOT уже использует собственные HP зверя.','Если медведь телепортируется вам за спину, спор о том, разумна ли природа, уже закончен.');
select private.druid_patch_feature_text('subclass:druid:moon',3,'moon-circle-forms','Формы круга и заклинания Луны','Максимальный CR зверя для вашей Дикой формы равен уровню друида / 3 с округлением вниз. Пока вы в форме, ваш КД равен большему из двух значений: обычный КД зверя или 13 + модификатор Мудрости. Из-за проектной совместимости с Дикой формой 2014 эта способность НЕ выдаёт временные HP 3 × уровень друида: используются HP зверя из базового правила. Заклинания Круга Луны всегда подготовлены, не занимают обычный лимит и могут накладываться вами даже в Дикой форме: с 3 уровня «Лечение ран», «Лунный луч», «Звёздный огонёк»; с 5 — «Призыв животных»; с 7 — «Источник лунного света»; с 9 — «Массовое лечение ран».','Лунный друид становится зверем лучше остальных. В этой кампании — без второго слоя временных HP, потому что одного медведя на одного медведя вполне достаточно.');
select private.druid_patch_feature_text('subclass:druid:moon',6,'moon-improved-forms','Улучшенные формы круга','Пока действует Дикая форма, при каждом попадании атакой формы выберите тип всего урона этой атаки: обычный тип атаки или излучающий. Кроме того, ко всем своим спасброскам Телосложения в Дикой форме добавляйте модификатор Мудрости.','Теперь зверь светится, лучше держит концентрацию и окончательно разрушает попытки охраны понять, что происходит.');
select private.druid_patch_feature_text('subclass:druid:moon',10,'moon-step-rules','Лунный шаг','Бонусным действием телепортируйтесь на расстояние до 30 футов в свободное видимое место. Следующий бросок атаки, который вы совершите до конца текущего хода, получает преимущество. Число применений равно модификатору Мудрости, минимум 1; все применения возвращаются после долгого отдыха. Без действия можно потратить ячейку заклинаний 2 уровня или выше и восстановить 1 использование Лунного шага; каждая восстановленная единица требует отдельной ячейки.','Тридцать футов лунного света — и медведь уже стоит там, где его никто не заказывал.');
select private.druid_patch_feature_text('subclass:druid:moon',14,'moon-lunar-form','Лунная форма','Один раз за ход, когда вы попадаете атакой формы Дикой формы, можно нанести цели дополнительно 2к10 излучающего урона. Кроме того, каждый раз при использовании Лунного шага можно взять с собой одно согласное существо, находящееся в пределах 10 футов от вас; после телепорта поместите его в свободное видимое место в пределах 10 футов от точки вашего прибытия.','Если телепортирующегося медведя было мало, теперь он может привести друга.');
select private.druid_patch_feature_text('subclass:druid:moon',14,'moon-step-upgrade-rules','Лунный шаг · спутник','С 14 уровня при каждом использовании Лунного шага можно одновременно телепортировать одно согласное существо, которое находится в пределах 10 футов от вас. Вы телепортируетесь по обычному правилу Лунного шага на расстояние до 30 футов в свободное видимое место, а спутник появляется в свободном видимом месте в пределах 10 футов от вашей точки назначения. Это не требует дополнительного использования Лунного шага.','Билет на лунный экспресс теперь включает одного пассажира. Багаж всё ещё на вашей совести.');

select private.druid_patch_template_copy('subclass:druid:sea','Тратит Дикую форму на десятиминутный Гнев моря, который повреждает и отталкивает выбранную цель; позднее шторм даёт плавание, полёт, сопротивления и может быть передан союзнику.','Круг Моря превращает использование Дикой формы в движущуюся эманацию шторма вокруг носителя. На высоких уровнях эманация расширяется, даёт мобильность и сопротивления и может быть развёрнута вокруг союзника.','Пять футов шторма вокруг человека — немного только до первого неудачного спасброска.');
select private.druid_patch_feature_text('subclass:druid:sea',3,'sea-wrath-rules','Гнев моря и заклинания Круга','Заклинания Круга всегда подготовлены и не занимают обычный лимит: с 3 уровня «Облако тумана», «Порыв ветра», «Луч холода», «Дребезги», «Громовая волна»; с 5 — «Молния», «Дыхание под водой»; с 7 — «Управление водой», «Ледяной шторм»; с 9 — «Призыв элементаля», «Удержание чудовища». Гнев моря: бонусным действием потратьте 1 Дикую форму и на 10 минут создайте вокруг себя эманацию океанских брызг радиусом 5 футов. Она заканчивается раньше, если вы прекращаете её без действия, создаёте Гнев моря снова или становитесь Недееспособны. При создании эманации и затем бонусным действием на последующих ходах выберите другое видимое существо внутри неё. Оно совершает спасбросок Телосложения против Сл ваших заклинаний. При провале цель получает холодный урон: бросьте число к6, равное модификатору Мудрости, минимум 1; если цель Большого размера или меньше, её также можно оттолкнуть от вас на расстояние до 15 футов. При успешном спасброске цель не получает этого урона и не отталкивается.','Персональный шторм с чёткой зоной ответственности. Юристы стихий наконец сделали что-то полезное.');
select private.druid_patch_feature_text('subclass:druid:sea',6,'sea-aquatic-affinity','Связь с водой','Радиус эманации Гнева моря увеличивается с 5 до 10 футов. Кроме того, вы получаете скорость плавания, равную своей текущей Скорости.','Шторм стал шире, друид — быстрее в воде. Рыбы начинают задавать вопросы о лицензии.');
select private.druid_patch_feature_text('subclass:druid:sea',10,'sea-stormborn','Рождённый бурей','Пока активен ваш Гнев моря, вы получаете скорость полёта, равную своей текущей Скорости, а также сопротивление урону холодом, электричеством и звуком. Когда Гнев моря заканчивается, эти преимущества заканчиваются вместе с ним.','К десятому уровню море решает, что ходить по земле было необязательной привычкой.');
select private.druid_patch_feature_text('subclass:druid:sea',14,'sea-oceanic-gift-rules','Дар океана','Когда создаёте Гнев моря, вместо себя можно выбрать одно согласное существо в пределах 60 футов и создать эманацию вокруг него. Это существо получает все преимущества Гнева моря, включая преимущества «Рождённого бурей», и для урона и спасброска способности использует ваш модификатор Мудрости и вашу Сл заклинаний. Если при создании потратить 2 использования Дикой формы вместо 1, одинаковые эманации одновременно существуют вокруг вас и выбранного существа. Их длительность и условия окончания остаются обычными для Гнева моря.','Шторм теперь можно выдать союзнику. В инструкции всё ещё нет пункта «не направлять на интерьер таверны», но здравый смысл никто не отменял.');

select private.druid_patch_template_copy('subclass:druid:stars','Звёздная карта даёт постоянно подготовленные чары и бесплатные Направляющие снаряды; Звёздная форма расходует Дикую форму и выбирает Лучника, Чашу или Дракона, а Космическое знамение меняет D20 Test реакцией.','Круг Звёзд использует физическую Звёздную карту как фокус, превращает Дикую форму в одно из трёх созвездий и позже получает ограниченную реакцию на чужие D20 Tests. Каждый режим Звёздной формы описан отдельно.','Астрология становится убедительнее, когда гороскоп способен сделать дальнюю атаку заклинанием.');
select private.druid_patch_feature_text('subclass:druid:stars',3,'stars-star-map-rules','Звёздная карта','У вас есть Звёздная карта — Крошечный предмет, который можно использовать как друидический фокус. Пока вы держите карту, «Указание» и «Направляющий снаряд» всегда подготовлены и не занимают обычный лимит. «Направляющий снаряд» можно сотворить без ячейки число раз, равное модификатору Мудрости, минимум 1; все бесплатные применения возвращаются после долгого отдыха. Обычные ячейки остаются дополнительным способом накладывать это заклинание. Если карта потеряна, проведите часовую церемонию, которую можно выполнить во время короткого или долгого отдыха, чтобы создать новую; прежняя карта при этом уничтожается.','Небо выдало вам карту, фокус и несколько бесплатных выстрелов. Подозрительно щедро, но спорить с созвездиями неудобно.');
select private.druid_patch_feature_text('subclass:druid:stars',3,'stars-starry-form-rules','Звёздная форма','Бонусным действием потратьте 1 использование Дикой формы и вместо превращения примите Звёздную форму на 10 минут. Ваши игровые параметры не меняются; вы излучаете яркий свет в радиусе 10 футов и тусклый ещё на 10. Форма заканчивается раньше, если вы прекращаете её без действия, становитесь Недееспособны или используете эту способность снова. При активации выберите одно созвездие. Лучник: при активации формы и затем бонусным действием на последующих своих ходах совершайте дальнюю атаку заклинанием по существу в пределах 60 футов; при попадании 1к8 + модификатор Мудрости излучающего урона. Чаша: когда вы накладываете заклинание с расходом ячейки и оно восстанавливает HP существу, вы или другое существо в пределах 30 футов от вас дополнительно восстанавливает 1к8 + модификатор Мудрости HP. Дракон: когда вы совершаете проверку Интеллекта, проверку Мудрости или спасбросок Телосложения для поддержания концентрации, результат 9 или меньше на к20 можно считать 10.','Лучник стреляет, Чаша лечит, Дракон запрещает кубу падать слишком низко. Наконец-то созвездия с должностными инструкциями.');
select private.druid_patch_feature_text('subclass:druid:stars',6,'stars-cosmic-omen-rules','Космическое знамение','После каждого долгого отдыха обратитесь к Звёздной карте и бросьте к6. Чётный результат даёт Благо, нечётный — Беду до следующего долгого отдыха. Пока активно Благо, когда видимое существо в пределах 30 футов собирается совершить D20 Test, реакцией бросьте 1к6 и добавьте результат к итогу этого теста. Пока активна Беда, при таком же триггере реакцией бросьте 1к6 и вычтите результат из итога. Число применений реакции равно модификатору Мудрости, минимум 1; все применения возвращаются после долгого отдыха.','Каждое утро космос решает, будете вы сегодня помогать статистике или портить её.');
select private.druid_patch_feature_text('subclass:druid:stars',10,'stars-twinkling','Мерцающие созвездия','Пока действует Звёздная форма, Лучник при попадании наносит 2к8 + модификатор Мудрости излучающего урона вместо 1к8 + Мудрость; дополнительное лечение Чаши становится 2к8 + модификатор Мудрости вместо 1к8 + Мудрость; Дракон даёт скорость полёта 20 футов и зависание. Кроме того, в начале каждого своего хода в Звёздной форме можно сменить текущее созвездие без нового расхода Дикой формы.','Созвездия получили повышение. Дракон теперь ещё и официально игнорирует землю.');
select private.druid_patch_feature_text('subclass:druid:stars',10,'stars-starry-form-upgrade-rules','Звёздная форма · усиление','С 10 уровня Звёздная форма использует усиленные значения: Лучник — 2к8 + Мудрость излучающего урона, Чаша — 2к8 + Мудрость дополнительного лечения, Дракон — скорость полёта 20 футов с зависанием. В начале каждого своего хода можно переключиться на другое созвездие без нового применения или расхода Дикой формы; остальные правила выбранного созвездия не меняются.','Та же звёздная схема, только теперь на ней больше мощности и меньше уважения к гравитации.');
select private.druid_patch_feature_text('subclass:druid:stars',14,'stars-full-of-stars','Полон звёзд','Пока действует Звёздная форма, вы получаете сопротивление дробящему, колющему и рубящему урону. Сопротивления заканчиваются одновременно со Звёздной формой и не требуют отдельного ресурса или действия.','К этому моменту друид уже настолько похож на карту ночного неба, что обычное оружие начинает сомневаться в выборе профессии.');

do $$
declare v_missing integer; v_vague integer;
begin
  with features as (
    select m->'payload'->>'description' as description, m->'payload'->>'authorComment' as author_comment
    from public.rule_templates rt
    join public.rule_template_levels rtl on rtl.template_id=rt.id
    cross join lateral jsonb_array_elements(coalesce(rtl.mechanics,'[]'::jsonb)) m
    where rt.is_active and (rt.catalog_key='class:druid' or rt.catalog_key like 'subclass:druid:%')
      and m->>'type'='grant' and m->>'target'='feature'
  )
  select count(*) into v_missing
  from features
  where nullif(btrim(description),'') is null or nullif(btrim(author_comment),'') is null;

  with features as (
    select m->'payload'->>'description' as description
    from public.rule_templates rt
    join public.rule_template_levels rtl on rtl.template_id=rt.id
    cross join lateral jsonb_array_elements(coalesce(rtl.mechanics,'[]'::jsonb)) m
    where rt.is_active and (rt.catalog_key='class:druid' or rt.catalog_key like 'subclass:druid:%')
      and m->>'type'='grant' and m->>'target'='feature'
  )
  select count(*) into v_vague
  from features
  where lower(coalesce(description,'')) ~ '(развивает направление|расширяет возможности|получает новые возможности|усиливает способность|усиливает возможности|согласно подклассу)';

  if v_missing > 0 then raise exception 'Druid text closure failed: % feature cards are missing description or authorComment', v_missing; end if;
  if v_vague > 0 then raise exception 'Druid text closure failed: % feature cards still contain vague placeholder language', v_vague; end if;
end;
$$;

commit;
